scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gUpDepCd = js_belngdepcd;
scwin.vScrenID = 'ULDSTF26400.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

// session 값을 control 에 binding 시키는 함수.
scwin.initPage = function() {
    /*
    	상위부서코드 재셋팅 : 2009.02.24
    	뒤에 3자리가 000이면 부서코드를 상위부서코드에 셋팅한다.
    */
    if (js_belngdepcd.substring(1, 4) == '000') {
        scwin.gUpDepCd = js_dep_cd;
    }
    if (js_market == "9") {
        $c.stf.setObjectValue(rdo_MKT_ID, "1");
        $c.stf.showObj(panel_mkt, true);
    } else {
        $c.stf.setObjectValue(rdo_MKT_ID, js_market);
        $c.stf.showObj(panel_mkt, false);

        // 유가 공시팀(26**), 코스닥 공시팀(34**) => 일때만 보여준다.
        if (js_dep_cd.substring(0, 2) == '26' || js_dep_cd.substring(0, 2) == '34') {
            $c.stf.showObj(panel_dep_emp, true);
            scwin.gDepCd = "UPTEAM";
        } else {
            $c.stf.showObj(panel_dep_emp, false);
        }
        scwin.setHeadTitle(); //년도 선택시 '숫자연도'로 표시, 기간선택시는 '당해'로 표시

    }
    dts_dep.DataID = "/CodeAction.do?method=getDepUpCode" + "&inputMessageId=CODE_EMPDEP_IN&outputMessageId=CODE_EMPDEP_OUT" + "&For=R&DEP_CD=" + js_dep_cd;
    dts_dep.Reset();
    // alert(gLdMktTp);

    dts_FormUpclss.DataID = "/CodeAction.do?method=listFormUpclss&For=R";
    dts_FormUpclss.Reset();
};
scwin.fn_SetCode = function() {
    var url = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT&FOR=R&CD_ENG_NM=FISCYY_TP_CD";
    //dts_FISCYY_TP_CD.DataID = url;
    //dts_FISCYY_TP_CD.Reset();

    var ToDay = new Date();
    var yyyy = parseInt(ToDay.getYear(), 10);
    var str = "";
    for (var i = yyyy; i >= 1980; i--) {
        str += i + "^" + i + ",";
    }
    str = str.substring(0, str.length - 1);
    //alert(str);
    cmb_YYYY.CBData = str;
    str = "^전체,";
    for (var i = 1; i <= 12; i++) {
        str += $c.ut.lpad(i, 2, "0") + "^" + $c.ut.lpad(i, 2, "0") + ",";
    }
    str = str.substring(0, str.length - 1);
    cmb_MM.CBData = str;
    if (js_market == "9") {

    } else {
        $c.stf.setObjectValue(rdo_MKT_ID, js_market);
        rdo_MKT_ID.setDisabled(true);
    }

    //회사속성 콤보박스 초기화
    dts_COMPANY_ATTRIBUTE.DataID = "/CodeAction.do?method=listCompanyAttribute&For=R";
    dts_COMPANY_ATTRIBUTE.Reset();
};
scwin.fn_SwitchSel = function() {
    var arr = new Array(cmb_FISCYY_TP_CD, cmb_MM);
    var a = $c.stf.getObjectValue(rdo_QuaOrMM);
    var b = (a == 0) ? 1 : 0;
    $c.stf.setObjectValue(arr[b], "");
    arr[a].setDisabled(false);
    arr[b].setDisabled(true);
};
scwin.fn_changGridHeader = function() {
    if ($c.stf.getObjectValue(rdo_year_type) == '1') {
        $c.cm.setColumnProp(grd_Grid, 'prevYear', 'Show', true);
    } else {
        $c.cm.setColumnProp(grd_Grid, 'prevYear', 'Show', false);
    }
};
scwin.fn_listDisclosureCountStatistics = function() {
    if (!scwin.fn_CheckBeforSearch()) {
        return;
    }
    $c.cm.ShowWin(grd_Grid);
    var url = "/DisclosureCountStatistics.do?method=listDisclosureCountStatistics";
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_MKT_ID); // 유가,코스닥 구분
    url += "&YEAR_TYPE=" + $c.stf.getObjectValue(rdo_year_type); // 유가,코스닥 구분
    url += "&YYYY=" + $c.stf.getObjectValue(cmb_YYYY); //년도
    url += "&FLAG=" + $c.stf.getObjectValue(rdo_QuaOrMM); // 0 : 분기, 1 : 달 구분.		
    url += "&FISCYY_TP_CD=" + $c.stf.getObjectValue(cmb_FISCYY_TP_CD); // 분기.
    url += "&MM=" + $c.stf.getObjectValue(cmb_MM); // 달.
    url += "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate); //FROM.
    url += "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate); // TO.
    url += "&SUBMIT_F=" + $c.stf.getObjectValue(chb_F); //신규
    url += "&SUBMIT_M=" + $c.stf.getObjectValue(chb_M); //정정
    url += "&SUBMIT_A=" + $c.stf.getObjectValue(chb_A); //첨부추가
    url += "&SUBMIT_U=" + $c.stf.getObjectValue(chb_U); //첨부정정
    url += "&DEP_CD=" + scwin.gDepCd; //부서코드
    url += "&UP_DEP_CD=" + scwin.gUpDepCd;
    url += "&UP_CLSS=" + $c.stf.getObjectValue(cmb_UPCLSS);
    url += "&KOR_YN=" + scwin.getChkValue(chb_kor_yn); //국문서식
    url += "&ENG_YN=" + scwin.getChkValue(chb_eng_yn); //영문서식
    url += "&DEP_TP=" + scwin.getChkValue(chb_dep_tp); //처리팀기준
    url += "&COM_TP_CD=" + $c.stf.getObjectValue(cmb_COMPANY_ATTRIBUTE); //회사속성
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    //alert(url);
    //return;
    dts_Grid.DataID = url;
    dts_Grid.Reset();
    /*
    url = "/DisclosureCountStatistics.do?method=listDisclosureCountTree";
    	url += "&MKT_ID=" + getObjectValue(rdo_MKT_ID);	
    	url += "&YYYY=" + getObjectValue(cmb_YYYY);
    	url += "&FLAG=" + getObjectValue(rdo_QuaOrMM);	// 0 : 분기, 1 : 달 구분.		
    	url += "&FISCYY_TP_CD=" + getObjectValue(cmb_FISCYY_TP_CD);	// 분기.
    	url += "&MM=" + getObjectValue(cmb_MM); // 달.
    	url += "&SUBMIT_F=" + getObjectValue(chb_F);
    	url += "&SUBMIT_M=" + getObjectValue(chb_M);	
    	url += "&SUBMIT_A=" + getObjectValue(chb_A);	
    	url += "&SUBMIT_U=" + getObjectValue(chb_U);	
    	url += "&DEP_CD=" +  gDepCd;		
    	url += "&UP_DEP_CD=" +  gUpDepCd;
    	url += "&KOR_YN=" + getChkValue(chb_kor_yn);
    	url += "&ENG_YN=" +  getChkValue(chb_eng_yn);
    	url += "&DEP_TP=" +  getChkValue(chb_dep_tp);			
    	//alert(url);
    dts_Tree.DataID = encodeURI(url);
    dts_Tree.Reset();
    */

};
scwin.fn_CheckBeforSearch = function() {
    // 언어구분 체크
    if (scwin.getChkValue(chb_kor_yn) == 0 && scwin.getChkValue(chb_eng_yn) == 0) {
        $c.win.alert("언어구분은 한개이상 선택하십시오.");
        chb_kor_yn.focus();
        return false;
    }
    scwin.gDepCd = $c.stf.getObjectValue(cmb_TeamList);
    var vF = $c.stf.getObjectValue(chb_F);
    var vM = $c.stf.getObjectValue(chb_M);
    var vA = $c.stf.getObjectValue(chb_A);
    var vU = $c.stf.getObjectValue(chb_U);
    if (vF == "N" && vM == "N" && vA == "N" && vU == "N") {
        $c.stf.setObjectValue(chb_F, "Y");
        $c.stf.setObjectValue(chb_M, "Y");
    }
    return true;
};
scwin.fn_Excel = function() {
    if (!scwin.fn_CheckBeforSearch()) {
        return;
    }
    var url = "/DisclosureCountStatistics.do?method=listDisclosureCountStatistics";
    url += "&MKT_ID=" + $c.stf.getObjectValue(rdo_MKT_ID); // 유가,코스닥 구분
    url += "&YEAR_TYPE=" + $c.stf.getObjectValue(rdo_year_type); // 유가,코스닥 구분
    url += "&YYYY=" + $c.stf.getObjectValue(cmb_YYYY); //년도
    url += "&FLAG=" + $c.stf.getObjectValue(rdo_QuaOrMM); // 0 : 분기, 1 : 달 구분.		
    url += "&FISCYY_TP_CD=" + $c.stf.getObjectValue(cmb_FISCYY_TP_CD); // 분기.
    url += "&MM=" + $c.stf.getObjectValue(cmb_MM); // 달.
    url += "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate); //FROM.
    url += "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate); // TO.
    url += "&SUBMIT_F=" + $c.stf.getObjectValue(chb_F); //신규
    url += "&SUBMIT_M=" + $c.stf.getObjectValue(chb_M); //정정
    url += "&SUBMIT_A=" + $c.stf.getObjectValue(chb_A); //첨부추가
    url += "&SUBMIT_U=" + $c.stf.getObjectValue(chb_U); //첨부정정
    url += "&DEP_CD=" + scwin.gDepCd; //부서코드
    url += "&UP_DEP_CD=" + scwin.gUpDepCd;
    url += "&UP_CLSS=" + $c.stf.getObjectValue(cmb_UPCLSS);
    url += "&KOR_YN=" + scwin.getChkValue(chb_kor_yn); //국문서식
    url += "&ENG_YN=" + scwin.getChkValue(chb_eng_yn); //영문서식
    url += "&DEP_TP=" + scwin.getChkValue(chb_dep_tp); //처리팀기준
    url += "&COM_TP_CD=" + $c.stf.getObjectValue(cmb_COMPANY_ATTRIBUTE); //회사속성
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts_Excel.DataID = url;
    dts_Excel.Reset();
};
scwin.fn_HideDebugCtrls = function() {
    $c.stf.showObj(panel_mkt, false);
    $c.stf.showObj(grd_Excel, false);
};


// 공시팀 전체 목록에 추가
scwin.fn_addDsclTeamAll = function(rowcount) {
    dts_dep.setCellData(2, "VALUE", 'UPTEAM'); //
    dts_dep.setCellData(2, "TEXT", '공시팀 전체');
    dts_dep.setCellData(2, "DEP_CD", 'UPTEAM');
    for (var i = 3; i <= rowcount; i++) {
        dts_dep.setCellData(i, "VALUE", dts_dep1.getCellData(i - 1, "VALUE")); //
        dts_dep.setCellData(i, "TEXT", dts_dep1.getCellData(i - 1, "TEXT"));
        dts_dep.setCellData(i, "DEP_CD", dts_dep1.getCellData(i - 1, "DEP_CD"));
    }
    dts_dep.insertRow();
    dts_dep.setCellData(rowcount + 1, "VALUE", dts_dep1.getCellData(rowcount, "VALUE")); //
    dts_dep.setCellData(rowcount + 1, "TEXT", dts_dep1.getCellData(rowcount, "TEXT"));
    dts_dep.setCellData(rowcount + 1, "DEP_CD", dts_dep1.getCellData(rowcount, "DEP_CD"));
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.setChkValue = function(obj, booleanVal) {
    //return (obj.checked) ? "Y" : "N";
    obj.setValue(booleanVal);
};
scwin.setHeadTitle = function() {
    if ($c.stf.getObjectValue(rdo_year_type) == '1') {
        curryear = $c.stf.getObjectValue(cmb_YYYY);
        lastyear = curryear - 1;
        $c.cm.setColumnProp(grd_Grid, 'currYear', 'Name', curryear + "년");
        $c.cm.setColumnProp(grd_Grid, 'prevYear', 'Name', lastyear + "년");
    } else {
        $c.cm.setColumnProp(grd_Grid, 'currYear', 'Name', "당해");
        $c.cm.setColumnProp(grd_Grid, 'prevYear', 'Name', "전해");
    }
};
scwin.btn_Search_onclick = function() {
    scwin.fn_listDisclosureCountStatistics();
};
scwin.rdo_QuaOrMM_OnSelChange = function() {
    scwin.fn_SwitchSel();
};
scwin.dts_Grid_OnLoadCompleted = function(rowcount) {
    var CURR_YYYY = dts_Grid.getCellData(1, "CURR_YYYY");
    var PREV_YYYY = dts_Grid.getCellData(1, "PREV_YYYY");
    $c.cm.setColumnProp(grd_Grid, "CURR_CNT", "name", CURR_YYYY + "년");
    $c.cm.setColumnProp(grd_Grid, "PREV_CNT", "name", PREV_YYYY + "년");
    $c.cm.CloseWin(rowcount, grd_Grid);
};
scwin.dts_Grid_OnLoadError = function() {
    $c.stf.alert_error(dts_Grid);
};
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    //파일형식 today_화면명.xls
    var xls_path = $c.session.getExcelDownPath() + today + "_공시건수통계.xlsx";
    if ($c.stf.getObjectValue(rdo_year_type) == '1') {
        $c.data.downloadGridViewOffice(grd_Grid, "공시건수통계", xls_path, 8, 0);
    } else {
        scwin.fn_Excel();
    }
};
scwin.dts_Excel_OnLoadCompleted = function(rowcount) {
    var today = $c.ut.cGetToday("yyyymmddhhmmss");
    //파일형식 today_화면명.xls
    var xls_path = $c.session.getExcelDownPath() + today + "_공시건수통계.xlsx";
    $c.data.downloadGridViewOffice(grd_Excel, "공시건수통계", xls_path, 8, 0);
};
scwin.dts_Excel_OnLoadError = function() {
    $c.stf.alert_error(dts_Excel);
};
scwin.btn_STATUS_onclick = function() {
    $c.frame.path("../../").GWinOpen("ULDSTF26500", "/dsclsrch/ULDSTF26500.gfm", "공시건수현황", 10, 10, 1270, 780, "");
    //frame.CreateDialogFrame("child01", "/dsclsrch/ULDSTF26500.gfm", "공시건수현황", 10, 10, 1270, 750, "window");

};
scwin.chb_dep_tp_onclick = function() {

};
scwin.dts_dep_OnLoadCompleted = function(rowcount) {
    if (js_dep_cd.substring(0, 2) == '26' || js_dep_cd.substring(0, 2) == '34') {
        $c.stf.CopyDataSet(dts_dep, dts_dep1);
        scwin.fn_addDsclTeamAll(rowcount);
        $c.stf.setObjectValue(cmb_TeamList, 'UPTEAM');
    }
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.rdo_year_type_OnSelChange = function() {
    scwin.setHeadTitle();
    scwin.fn_changGridHeader();
    dts_Grid.removeAll();
    dts_Excel.removeAll();
};
scwin.cmb_YYYY_OnSelChange = function() {
    scwin.setHeadTitle();
};
scwin.gform_onload = function() {
    scwin.fn_HideDebugCtrls();
    $c.cm.PanelToGroupBox(panel_1);
    scwin.fn_SetCode();
    scwin.initPage();
};
